SELECT 'montagem_nonnull|' || count(*) || '|' || count(codigo_poste) || '|' || count(descricao_poste) || '|' || count(codigo_produto) FROM public.montagem_poste;
SELECT 'api_columns|' || table_name || '|' || string_agg(column_name, ',' ORDER BY ordinal_position) FROM information_schema.columns WHERE table_schema='api' AND table_name IN ('usuarios','programacao_pcp','liberacao_formas','producao','montagem_poste','formas_manutencao','prog_s3_s4','vw_formas_status') GROUP BY table_name ORDER BY table_name;
SELECT 'public_indexes|' || tablename || '|' || indexname FROM pg_indexes WHERE schemaname='public' AND tablename IN ('usuarios','programacao_pcp','liberacao_formas','producao','montagem_poste','formas_manutencao','prog_s3_s4') ORDER BY tablename,indexname;
SELECT 'public_triggers|' || event_object_table || '|' || trigger_name FROM information_schema.triggers WHERE event_object_schema='public' AND event_object_table IN ('usuarios','programacao_pcp','liberacao_formas','producao','montagem_poste','formas_manutencao','prog_s3_s4') ORDER BY event_object_table,trigger_name;
SELECT 'montagem_sample|' || left(md5(id),12) || '|' || (codigo_poste IS NOT NULL)::text || '|' || (descricao_poste IS NOT NULL)::text || '|' || (codigo_produto IS NOT NULL)::text FROM public.montagem_poste WHERE codigo_poste IS NOT NULL OR descricao_poste IS NOT NULL OR codigo_produto IS NOT NULL ORDER BY created_at DESC LIMIT 5;
SELECT 'column_type|' || table_schema || '|' || table_name || '|' || column_name || '|' || data_type || '|' || coalesce(udt_name,'') FROM information_schema.columns WHERE (table_schema='public' AND table_name IN ('usuarios','programacao_pcp','liberacao_formas','producao','montagem_poste','formas_manutencao','prog_s3_s4')) OR (table_schema='api' AND table_name='vw_formas_status') ORDER BY table_schema,table_name,ordinal_position;
